-- Subject set: the flight lead's missions, assignedSquadron IN subject.squadrons OR bookedBy = subject, under bare-column tenancy.
SELECT Id, SectorId, ClientId, KindId, Title, Brief, Hazard, Fee, Deadline, RequiredCertId, BookedByUserId, AssignedSquadronId, StatusId, Notes FROM Missions WHERE (`Missions`.`SectorId` = 'a1111111-1111-4111-8111-111111111111') AND (EXISTS (SELECT 1 FROM `SquadronMemberships` `ca1` WHERE `ca1`.`UserId` = 'f0000000-0000-4000-8000-000000000006' AND `ca1`.`SquadronId` = `Missions`.`AssignedSquadronId` AND EXISTS (SELECT 1 FROM `Squadrons` `ca2` WHERE `ca2`.`Id` = `ca1`.`SquadronId` AND EXISTS (SELECT 1 FROM `Wings` `ca3` WHERE `ca3`.`Id` = `ca2`.`WingId` AND `ca3`.`SectorId` = 'a1111111-1111-4111-8111-111111111111'))) OR `Missions`.`BookedByUserId` = 'f0000000-0000-4000-8000-000000000006') ORDER BY `Deadline` ASC, `Id` ASC LIMIT 26
